@ServerEndpoint("/chat")
public class ChatEndpoint {

    private final Map<String, Session> sessions = new HashMap<>();

    @OnOpen
    public void onOpen(Session s) {
        sessions.put(s.getId(), s);
    }

    @OnMessage
    public void onMessage(String text) {
        sessions.values().forEach(s -> send(s, text));
    }
}

